import { useEffect, useId, useMemo, useRef, useState } from "react";
import { DialogHeader } from "@kerfjs/ui/dialog-header";
import { EmptyState } from "@kerfjs/ui/empty-state";
import "@kerfjs/ui/layout.css";
import "./CommandPalette.css";

// The supplied package guidance lists DialogHeader and EmptyState, but does
// not establish a CommandPalette export. This composition does not invent one.
// Command definitions, matching and history persistence belong to the app.
export type Command = { id: string; label: string; group: string; run: () => void };
export function CommandPalette({ open, commands, recentIds, onRecentIdsChange, onClose }: {
  open: boolean; commands: Command[]; recentIds: string[];
  onRecentIdsChange: (ids: string[]) => void; onClose: () => void;
}) {
  const modal = useRef<HTMLDialogElement>(null);
  const input = useRef<HTMLInputElement>(null);
  const base = useId();
  const [query, setQuery] = useState("");
  const [active, setActive] = useState(0);
  const groups = useMemo(() => {
    const matches = commands.filter(c => c.label.toLocaleLowerCase().includes(query.trim().toLocaleLowerCase()));
    const recent = query.trim() ? [] : recentIds.map(id => matches.find(c => c.id === id)).filter((c): c is Command => !!c);
    const used = new Set(recent.map(c => c.id));
    const result: { label: string; commands: Command[] }[] = recent.length ? [{ label: "Recent", commands: recent }] : [];
    for (const command of matches) {
      if (used.has(command.id)) continue;
      let group = result.find(g => g.label === command.group && g.label !== "Recent");
      if (!group) { group = { label: command.group, commands: [] }; result.push(group); }
      group.commands.push(command);
    }
    return result;
  }, [commands, query, recentIds]);
  const flat = groups.flatMap(group => group.commands);
  const index = Math.min(active, Math.max(0, flat.length - 1));
  useEffect(() => {
    const element = modal.current;
    if (!element) return;
    const previous = document.activeElement instanceof HTMLElement ? document.activeElement : null;
    if (open) { setQuery(""); setActive(0); if (!element.open) element.showModal(); input.current?.focus(); }
    else if (element.open) element.close();
    return () => { if (element.open) element.close(); if (open && previous?.isConnected) previous.focus(); };
  }, [open]);
  useEffect(() => {
    if (!open || !flat.length) return;
    document.getElementById(base + "-option-" + index)?.scrollIntoView({ block: "nearest" });
  }, [open, index, query, flat.length, base]);
  function execute(command: Command) {
    onRecentIdsChange([command.id, ...recentIds.filter(id => id !== command.id)].slice(0, 10));
    onClose();
    command.run();
  }
  let position = 0;
  return <dialog ref={modal} className="kui-layout command-dialog"
    aria-labelledby={base + "-title"} aria-describedby={base + "-summary"}
    onCancel={e => { e.preventDefault(); onClose(); }}>
    <DialogHeader>
      <h2 id={base + "-title"}>Commands</h2>
      <p id={base + "-summary"}>Search commands. Use Up and Down to select, Enter to run, and Escape to close.</p>
    </DialogHeader>
    <div className="command-search">
      <label htmlFor={base + "-input"}>Find a command</label>
      <input ref={input} id={base + "-input"} role="combobox" autoComplete="off"
        aria-autocomplete="list" aria-expanded="true" aria-controls={base + "-results"}
        aria-activedescendant={flat.length ? base + "-option-" + index : undefined}
        value={query} onChange={e => { setQuery(e.target.value); setActive(0); }}
        onKeyDown={e => {
          if (e.nativeEvent.isComposing) return;
          if (e.key === "ArrowDown" || e.key === "ArrowUp") {
            e.preventDefault();
            if (flat.length) setActive((index + (e.key === "ArrowDown" ? 1 : -1) + flat.length) % flat.length);
          } else if (e.key === "Enter") {
            e.preventDefault(); if (flat[index]) execute(flat[index]);
          }
        }} />
    </div>
    <div className="command-results">
      <div role="listbox" aria-label="Commands" id={base + "-results"}>
        {groups.map((group, groupIndex) => <div key={groupIndex} role="group" aria-labelledby={base + "-group-" + groupIndex}>
          <div id={base + "-group-" + groupIndex}>{group.label}</div>
          {group.commands.map(command => {
            const optionIndex = position++;
            return <div role="option" id={base + "-option-" + optionIndex}
              aria-selected={index === optionIndex} key={command.id}
              onPointerMove={() => setActive(optionIndex)}
              onMouseDown={e => e.preventDefault()} onClick={() => execute(command)}>
              {index === optionIndex && <span aria-hidden="true">› </span>}{command.label}
            </div>;
          })}
        </div>)}
      </div>
      {flat.length === 0 && <EmptyState title="No commands found" description="Try another search." />}
    </div>
    <div role="status" aria-live="polite">{flat.length} commands available</div>
    <footer><button type="button" onClick={onClose}>Close</button></footer>
  </dialog>;
}

