.command-dialog { padding: 0; width: min(36rem, calc(100vw - 2rem)); max-height: calc(100dvh - 2rem); overflow: hidden; }
.command-dialog[open] { display: flex; flex-direction: column; }
.command-dialog::backdrop { background: rgb(0 0 0 / .45); }
.command-search, .command-dialog footer { padding: var(--kui-dialog-padding, 1rem); }
.command-search { display: grid; gap: var(--kui-control-gap, .5rem); }
.command-search input { min-width: 0; min-height: 2.75rem; font: inherit; }
.command-results { overflow: auto; min-height: 0; padding: var(--kui-pane-padding, 1rem); }
.command-results [role="option"] { min-height: 2.75rem; display: flex; align-items: center; cursor: pointer; }
.command-results [aria-selected="true"] { outline: 2px solid currentColor; outline-offset: -2px; font-weight: 600; }
.command-dialog button { min-height: 2.75rem; }
.command-dialog :focus-visible { outline: 2px solid currentColor; outline-offset: 2px; }
